def transform(grid):
    h, w = len(grid), len(grid[0])
    special = {v for row in grid for v in row if v not in (0, next(iter({x for r in grid for x in r if x not in (0,)}), 0))}
    # The patterned marker color is the nonzero color other than the dominant background.
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    bg = max((v for v in counts if v != 0), key=lambda v: counts[v])
    colors = [v for v in counts if v not in (0, bg)]
    mark = colors[0]
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == mark]
    r0, c0 = min(r for r, c in pts), min(c for r, c in pts)
    shape = [(r-r0, c-c0) for r, c in pts]
    sh, sw = max(r for r, c in shape)+1, max(c for r, c in shape)+1
    out = [row[:] for row in grid]
    for r in range(h-sh+1):
        for c in range(w-sw+1):
            if all(grid[r+dr][c+dc] == 0 for dr, dc in shape):
                for dr, dc in shape:
                    out[r+dr][c+dc] = mark
    return out
